import { Command } from '@ckeditor/ckeditor5-core';

/** The name under which {@link MermaidExampleCommand} is registered in the editor. */
export const MERMAID_EXAMPLE_COMMAND = 'mermaidExampleCommand';

/**
 * Replaces the source of the selected diagram with an example one. Writing the attribute is a
 * single model change, so the author can undo it in one step if they picked the wrong type.
 */
export default class MermaidExampleCommand extends Command {

	refresh() {
		this.isEnabled = !!this._selectedDiagram();
	}

	execute( { source } = {} ) {
		const diagram = this._selectedDiagram();

		if ( !diagram || !source ) {
			return;
		}

		this.editor.model.change( writer => {
			writer.setAttribute( 'source', source, diagram );
		} );
	}

	_selectedDiagram() {
		const selectedElement = this.editor.model.document.selection.getSelectedElement();

		return selectedElement?.is( 'element', 'mermaid' ) ? selectedElement : null;
	}
}
